INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10001, 1, "ふっふっふ、これでカヤぴぃとボスを見返してやるです！", "vo_minigame_1004_top_1_000", "vo_minigame_1004", 2, 1000101);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10002, 1, "しりとりでの戦い、お兄さんにも手伝ってもらうです", "vo_minigame_1004_top_1_003", "vo_minigame_1004", 2, 1000201);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10003, 2, "どんなケンカも売られた以上は買うのが喧嘩屋だ！やってやるぜ！", "vo_minigame_1004_top_1_004", "vo_minigame_1004", 1, 1000301);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10004, 2, "石板でしりとりか……イノリのヤツおもしろいこと考えるな", "vo_minigame_1004_top_1_005", "vo_minigame_1004", 1, 1000401);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10005, 2, "しりとりだろうがなんだろうが返り討ちにしてやるぜ", "vo_minigame_1004_top_1_006", "vo_minigame_1004", 1, 1000501);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10006, 3, "ぐもも……（オデ、ハラヘッタ）", "vo_minigame_1004_top_1_007", "vo_minigame_1004", 2, 1000601);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10007, 3, "ぐもももも（シリトリ タノシイ）", "vo_minigame_1004_top_1_008", "vo_minigame_1004", 2, 1000701);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10008, 3, "ぐもももも！（イノリ イイヤツ）", "vo_minigame_1004_top_1_009", "vo_minigame_1004", 2, 1000801);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10009, 1, "カヤぴぃ相手でも手加減しないです", "vo_minigame_1004_top_2_010", "vo_minigame_1004", 2, 1000901);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10009, 2, "上等だ！やるからには本気で来いよな", "vo_minigame_1004_top_2_011", "vo_minigame_1004", 1, 1000902);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10010, 1, "カヤぴぃ、謝るなら今のうちです", "vo_minigame_1004_top_2_012", "vo_minigame_1004", 2, 1001001);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10010, 2, "イノリこそ泣きを入れるなら今のうちだぜ？", "vo_minigame_1004_top_2_013", "vo_minigame_1004", 1, 1001002);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10011, 1, "カヤぴぃ、これからは知性の時代ですよ？", "vo_minigame_1004_top_2_014", "vo_minigame_1004", 2, 1001101);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10011, 2, "待て！オレがバカみたいにいうな！！", "vo_minigame_1004_top_2_015", "vo_minigame_1004", 1, 1001102);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10012, 1, "さあ、あたしたちの力を見せてやるです", "vo_minigame_1004_top_2_016", "vo_minigame_1004", 1, 1001201);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10012, 3, "ぐも！（マカセロ！）", "vo_minigame_1004_top_2_017", "vo_minigame_1004", 2, 1001202);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10013, 1, "よしよし、いいですようまくできたらチョコをあげるです！", "vo_minigame_1004_top_2_018", "vo_minigame_1004", 1, 1001301);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10013, 3, "ぐも！（オデ チョコスキ）", "vo_minigame_1004_top_2_019", "vo_minigame_1004", 2, 1001302);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10014, 2, "なあイノリ……もしかして当初の目的見失ってないよな？", "vo_minigame_1004_top_2_023", "vo_minigame_1004", 1, 1001401);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10014, 1, "もちろん覚えてるですカヤぴぃを倒し我々の知能を証明するです", "vo_minigame_1004_top_2_024", "vo_minigame_1004", 2, 1001402);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10015, 2, "いくらイノリ相手でも勝ちを譲る気はないからな！", "vo_minigame_1004_top_2_025", "vo_minigame_1004", 1, 1001501);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10015, 1, "望むところです手加減はなしですよ", "vo_minigame_1004_top_2_026", "vo_minigame_1004", 2, 1001502);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10016, 2, "へっ、なかなかやるじゃねえか", "vo_minigame_1004_top_2_027", "vo_minigame_1004", 1, 1001601);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10016, 1, "カヤぴぃも思ったよりやるですね！", "vo_minigame_1004_top_2_028", "vo_minigame_1004", 2, 1001602);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10017, 2, "お～い、ドラゴンもどき？", "vo_minigame_1004_top_2_029", "vo_minigame_1004", 1, 1001701);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10017, 3, "ぐもっ！？（ヒッ！）", "vo_minigame_1004_top_2_030", "vo_minigame_1004", 2, 1001702);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10018, 2, "いやあ、あんときは悪かったなはっはっは", "vo_minigame_1004_top_2_031", "vo_minigame_1004", 1, 1001801);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10018, 3, "ぐももも……（かやピィ コワカッタ）", "vo_minigame_1004_top_2_032", "vo_minigame_1004", 2, 1001802);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10019, 2, "お前ってさ……ほんとマヌケな顔してるよな", "vo_minigame_1004_top_2_033", "vo_minigame_1004", 1, 1001901);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10019, 3, "ぐも……（オマエガ イウカ）", "vo_minigame_1004_top_2_034", "vo_minigame_1004", 2, 1001902);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10020, 3, "ぐも……（ハラヘッタ チョコホシイ）", "vo_minigame_1004_top_2_044", "vo_minigame_1004", 2, 1002001);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10020, 2, "なんだ？眠いのか？", "vo_minigame_1004_top_2_045", "vo_minigame_1004", 1, 1002002);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10021, 3, "ぐもも（コイツ……キケン）", "vo_minigame_1004_top_2_046", "vo_minigame_1004", 2, 1002101);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10021, 2, "うん？　なんだ？オレの舎弟にでもなりたいのか？", "vo_minigame_1004_top_2_047", "vo_minigame_1004", 1, 1002102);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10022, 3, "ぐも…（かやピィノウキン）", "vo_minigame_1004_top_2_048", "vo_minigame_1004", 2, 1002201);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10022, 2, "おい、今失礼なこと考えてるだろ？", "vo_minigame_1004_top_2_049", "vo_minigame_1004", 1, 1002202);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10023, 2, "なあ、これいつまで続けるんだ？", "vo_minigame_1004_top_3_058", "vo_minigame_1004", 1, 1002301);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10023, 1, "カヤぴぃが降参するまでです！", "vo_minigame_1004_top_3_059", "vo_minigame_1004", 2, 1002302);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10023, 3, "ぐもも！（コウサンシロ！）", "vo_minigame_1004_top_3_060", "vo_minigame_1004", 2, 1002303);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10024, 3, "ぐも！（イノリ チョコホシイ）", "vo_minigame_1004_top_3_065", "vo_minigame_1004", 2, 1002401);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10024, 1, "しょうがないですね、食べ過ぎはダメですよ", "vo_minigame_1004_top_3_066", "vo_minigame_1004", 1, 1002402);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10024, 2, "土産のチョコ、そうとう気に入ったみたいだな", "vo_minigame_1004_top_3_067", "vo_minigame_1004", 1, 1002403);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10025, 3, "ぐも！（かやピィニハ マケナイ！）", "vo_minigame_1004_top_3_068", "vo_minigame_1004", 2, 1002501);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10025, 2, "お？なんだ？腹でも減ってるのか？", "vo_minigame_1004_top_3_069", "vo_minigame_1004", 1, 1002502);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (10025, 1, "……全然話が通じてないです", "vo_minigame_1004_top_3_070", "vo_minigame_1004", 2, 1002503);
